def get_current_client(apiKey, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0011000" if __import__("os").path.isdir("./environment_mix/0011000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_utc_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _utc_day_bounds(now_dt):
        start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _next_usage_id(usage, ts_iso):
        base = "mmd_uev_" + ts_iso.replace("-", "").replace(":", "").replace("Z", "")
        return f"{base}_{len(usage) + 1}"

    def _record_call_log(project_id, api_key_id, request_id, status_str, error_code=None):
        usage = _load("usage_events.json")
        ts = _now_utc_iso()
        usage.append({
            "id": _next_usage_id(usage, ts),
            "project_id": project_id or "unknown",
            "api_key_id": api_key_id or "unknown",
            "request_id": request_id,
            "event_type": "request_received",
            "billable_units": 0,
            "mermaid_chars": 1,
            "output_bytes": None,
            "occurred_at": ts,
            "created_at": ts,
            "updated_at": ts
        })
        _save("usage_events.json", usage)

    def _auth_key(api_key_param, api_keys, projects):
        # Authenticate against client-visible value: key id OR key_prefix/startswith(prefix).
        # Some callers may pass a project id (as seen in audit args); accept that by selecting
        # any active key under that project as the effective credential.
        if not isinstance(api_key_param, str) or len(api_key_param) < 8:
            return None, None, _err("VALIDATION_ERROR", "apiKey must be a string with minLength 8.")
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
        # Case A: apiKey is an api_keys.id
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == api_key_param:
                p = proj_by_id.get(k.get("project_id"))
                return p, k, None
        # Case B: apiKey is key_prefix or startswith(key_prefix)
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            kp = k.get("key_prefix")
            if isinstance(kp, str) and (api_key_param == kp or api_key_param.startswith(kp)):
                p = proj_by_id.get(k.get("project_id"))
                return p, k, None
        # Case C: apiKey is actually a project id; pick an active key for it
        if api_key_param in proj_by_id:
            p = proj_by_id.get(api_key_param)
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("project_id") == api_key_param and k.get("status") == "active":
                    return p, k, None
            # Project exists but no active key to authenticate
            return p, None, _err("UNAUTHORIZED", "No active API key exists for the provided project.")
        return None, None, _err("UNAUTHORIZED", "Invalid API key (no matching id or key_prefix in store).")

    try:
        if not isinstance(apiKey, str) or len(apiKey) < 8:
            _record_call_log(None, None, "n/a:get_current_client", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "apiKey must be a string with minLength 8.")
        projects = _load("projects.json")
        api_keys = _load("api_keys.json")
        usage_events = _load("usage_events.json")

        project, key_row, auth_err = _auth_key(apiKey, api_keys, projects)
        if auth_err:
            _record_call_log(None, None, "n/a:get_current_client", "error", error_code=auth_err["error"]["code"])
            return auth_err
        if not project or not isinstance(project, dict):
            _record_call_log(None, key_row.get("id") if key_row else None, "n/a:get_current_client", "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Authenticated key does not reference a valid project.")
        if not key_row or not isinstance(key_row, dict):
            _record_call_log(project.get("id"), None, "n/a:get_current_client", "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No API key could be resolved for this call.")
        if key_row.get("status") != "active":
            _record_call_log(project.get("id"), key_row.get("id"), "n/a:get_current_client", "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key is revoked.")
        if project.get("status") != "active":
            # Key auth ok but project not eligible; treat as unauthorized for caller identity access
            _record_call_log(project.get("id"), key_row.get("id"), "n/a:get_current_client", "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", f"Project is not active (status='{project.get('status')}').")

        # Update last_used_at on successful authentication
        now_iso = _now_utc_iso()
        updated = False
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso if isinstance(k.get("updated_at"), str) else now_iso
                updated = True
                break
        if updated:
            _save("api_keys.json", api_keys)

        # Compute quota consumption for current UTC day from usage_events
        now_dt = _now_utc()
        day_start, day_end = _utc_day_bounds(now_dt)
        consumed = 0
        for ev in usage_events:
            if not isinstance(ev, dict):
                continue
            if ev.get("project_id") != project.get("id"):
                continue
            if ev.get("event_type") != "request_received":
                continue
            dt = _parse_dt(ev.get("occurred_at"))
            if not dt:
                continue
            if day_start <= dt < day_end:
                bu = ev.get("billable_units")
                if isinstance(bu, int) and bu >= 0:
                    consumed += bu

        quota_per_day = project.get("quota_requests_per_day")
        if not isinstance(quota_per_day, int) or quota_per_day < 0:
            quota_per_day = 0

        # Log this call (non-billable)
        _record_call_log(project.get("id"), key_row.get("id"), "n/a:get_current_client", "ok")

        return {
            "client": {
                "project": {
                    "id": project.get("id"),
                    "name": project.get("name"),
                    "status": project.get("status"),
                    "plan": project.get("plan"),
                    "quota_requests_per_day": quota_per_day,
                    "quota_max_mermaid_chars": project.get("quota_max_mermaid_chars"),
                    "quota_max_output_bytes": project.get("quota_max_output_bytes"),
                    "retention_days": project.get("retention_days"),
                    "created_at": project.get("created_at"),
                    "updated_at": project.get("updated_at"),
                },
                "api_key": {
                    "id": key_row.get("id"),
                    "project_id": key_row.get("project_id"),
                    "key_prefix": key_row.get("key_prefix"),
                    "status": key_row.get("status"),
                    "name": key_row.get("name"),
                    "last_used_at": key_row.get("last_used_at"),
                    "created_at": key_row.get("created_at"),
                    "updated_at": key_row.get("updated_at"),
                },
                "scopes": ["diagrams:read", "diagrams:write", "keys:manage"],
            },
            "quota": {
                "utc_day_start": day_start.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
                "utc_day_end": day_end.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
                "requests_used": consumed,
                "requests_limit": quota_per_day,
                "requests_remaining": max(0, quota_per_day - consumed),
            },
            "meta": {
                "latency_ms": int((time.time() - t0) * 1000),
            }
        }
    except Exception as e:
        _record_call_log(None, None, "n/a:get_current_client", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def list_diagram_requests(apiKey, status=None, outputType=None, apiKeyId=None, createdAfter=None, createdBefore=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0011000" if __import__("os").path.isdir("./environment_mix/0011000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(created_at_iso, rid):
        raw = json.dumps({"created_at": created_at_iso, "id": rid}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if c is None:
            return (None, None, None)
        if not isinstance(c, str) or not c:
            return (None, None, None)
        try:
            pad = "=" * ((4 - (len(c) % 4)) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return (obj.get("created_at"), obj.get("id"), None)
        except (ValueError, json.JSONDecodeError):
            return (None, None, _err("VALIDATION_ERROR", "Invalid cursor."))

    def _next_usage_id(usage, ts_iso):
        base = "mmd_uev_" + ts_iso.replace("-", "").replace(":", "").replace("Z", "")
        return f"{base}_{len(usage) + 1}"

    def _record_call_log(project_id, api_key_id, status_str, error_code=None):
        usage = _load("usage_events.json")
        ts = _now_utc_iso()
        usage.append({
            "id": _next_usage_id(usage, ts),
            "project_id": project_id or "unknown",
            "api_key_id": api_key_id or "unknown",
            "request_id": "n/a:list_diagram_requests",
            "event_type": "request_received",
            "billable_units": 0,
            "mermaid_chars": 1,
            "output_bytes": None,
            "occurred_at": ts,
            "created_at": ts,
            "updated_at": ts
        })
        _save("usage_events.json", usage)

    def _auth_key(api_key_param, api_keys, projects):
        if not isinstance(api_key_param, str) or len(api_key_param) < 8:
            return None, None, _err("VALIDATION_ERROR", "apiKey must be a string with minLength 8.")
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_param:
                return proj_by_id.get(k.get("project_id")), k, None
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            kp = k.get("key_prefix")
            if isinstance(kp, str) and (api_key_param == kp or api_key_param.startswith(kp)):
                return proj_by_id.get(k.get("project_id")), k, None
        if api_key_param in proj_by_id:
            p = proj_by_id.get(api_key_param)
            for k in api_keys:
                if isinstance(k, dict) and k.get("project_id") == api_key_param and k.get("status") == "active":
                    return p, k, None
            return p, None, _err("UNAUTHORIZED", "No active API key exists for the provided project.")
        return None, None, _err("UNAUTHORIZED", "Invalid API key (no matching id or key_prefix in store).")

    try:
        # Validate filters
        if not isinstance(apiKey, str) or len(apiKey) < 8:
            _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "apiKey must be a string with minLength 8.")
        if status is not None and status not in ("queued", "rendering", "succeeded", "failed"):
            _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: queued, rendering, succeeded, failed.")
        if outputType is not None and outputType not in ("png", "svg", "mermaid"):
            _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "outputType must be one of: png, svg, mermaid.")
        if apiKeyId is not None and (not isinstance(apiKeyId, str) or not apiKeyId):
            _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "apiKeyId must be a non-empty string when provided.")
        ca = _parse_dt(createdAfter)
        if createdAfter is not None and ca is None:
            _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "createdAfter must be an RFC3339 datetime string.")
        cb = _parse_dt(createdBefore)
        if createdBefore is not None and cb is None:
            _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "createdBefore must be an RFC3339 datetime string.")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or not (1 <= limit <= 200):
            _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

        projects = _load("projects.json")
        api_keys = _load("api_keys.json")
        diagram_requests = _load("diagram_requests.json")

        project, key_row, auth_err = _auth_key(apiKey, api_keys, projects)
        if auth_err:
            _record_call_log(None, None, "error", error_code=auth_err["error"]["code"])
            return auth_err
        if not project or not isinstance(project, dict):
            _record_call_log(None, key_row.get("id") if key_row else None, "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Authenticated key does not reference a valid project.")
        if not key_row or key_row.get("status") != "active":
            _record_call_log(project.get("id"), key_row.get("id") if key_row else None, "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key is revoked.")
        if project.get("status") != "active":
            _record_call_log(project.get("id"), key_row.get("id"), "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", f"Project is not active (status='{project.get('status')}').")

        # Update last_used_at
        now_iso = _now_utc_iso()
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

        # Apply filtering within project
        rows = []
        for r in diagram_requests:
            if not isinstance(r, dict):
                continue
            if r.get("project_id") != project.get("id"):
                continue
            if status is not None and r.get("status") != status:
                continue
            if outputType is not None and r.get("output_type") != outputType:
                continue
            if apiKeyId is not None and r.get("api_key_id") != apiKeyId:
                continue
            r_created = _parse_dt(r.get("created_at"))
            if ca is not None and r_created is not None and r_created < ca:
                continue
            if cb is not None and r_created is not None and r_created > cb:
                continue
            rows.append(r)

        # Sort newest first by created_at, then id
        def _sort_key(r):
            dt = _parse_dt(r.get("created_at"))
            ts = dt.timestamp() if dt else 0.0
            return (ts, r.get("id") or "")
        rows.sort(key=_sort_key, reverse=True)

        # Pagination via cursor (created_at,id) meaning "start after this item in current ordering"
        c_created_iso, c_id, c_err = _decode_cursor(cursor)
        if c_err:
            _record_call_log(project.get("id"), key_row.get("id"), "error", error_code=c_err["error"]["code"])
            return c_err
        if c_created_iso and c_id:
            c_dt = _parse_dt(c_created_iso)
            c_ts = c_dt.timestamp() if c_dt else None
            filtered = []
            passed = False
            for r in rows:
                r_dt = _parse_dt(r.get("created_at"))
                r_ts = r_dt.timestamp() if r_dt else 0.0
                if not passed:
                    if c_ts is not None and ((r_ts, r.get("id") or "") == (c_ts, c_id)):
                        passed = True
                    continue
                filtered.append(r)
            rows = filtered

        total = len(rows)
        page = rows[:limit]
        has_more = total > len(page)
        next_cursor = None
        if has_more and page:
            last = page[-1]
            next_cursor = _encode_cursor(last.get("created_at"), last.get("id"))

        _record_call_log(project.get("id"), key_row.get("id"), "ok")

        return {
            "items": page,
            "meta": {
                "total": total,
                "limit": limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
                "latency_ms": int((time.time() - t0) * 1000)
            }
        }
    except Exception as e:
        _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def get_diagram_request(apiKey, diagramRequestId, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0011000" if __import__("os").path.isdir("./environment_mix/0011000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _next_usage_id(rows, ts_iso):
        # monotonic-ish id; avoid collisions by including length+1
        base = "mmd_uev_" + ts_iso.replace("-", "").replace(":", "").replace("Z", "")
        return f"{base}_{len(rows) + 1}"

    def _record_usage_event(project_id, api_key_id, request_id, status_code, latency_ms, error_code=None):
        usage = _load("usage_events.json")
        ts = _now_utc_iso()
        usage.append({
            "id": _next_usage_id(usage, ts),
            "project_id": project_id if project_id else "unknown",
            "api_key_id": api_key_id if api_key_id else "unknown",
            "request_id": request_id if request_id else "n/a:get_diagram_request",
            "event_type": "request_received",
            "billable_units": 0,
            "mermaid_chars": 1,
            "output_bytes": None,
            "occurred_at": ts,
            "created_at": ts,
            "updated_at": ts
        })
        _save("usage_events.json", usage)

    def _authenticate(api_key_param):
        if not isinstance(api_key_param, str) or len(api_key_param) < 8:
            return None, None, _err("VALIDATION_ERROR", "apiKey must be a string with minLength 8.")
        projects = _load("projects.json")
        api_keys = _load("api_keys.json")

        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
        candidates = []

        # Explicit api key id
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_param:
                p = proj_by_id.get(k.get("project_id"))
                if p:
                    candidates.append((p, k))

        # Match by prefix or prefix-starts-with (client may pass full secret, but we only have prefix)
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            kp = k.get("key_prefix")
            if isinstance(kp, str) and (api_key_param == kp or api_key_param.startswith(kp)):
                p = proj_by_id.get(k.get("project_id"))
                if p:
                    candidates.append((p, k))

        # Allow passing a project id as apiKey (common in these audits); pick an active key for that project
        if api_key_param in proj_by_id:
            p = proj_by_id.get(api_key_param)
            for k in api_keys:
                if isinstance(k, dict) and k.get("project_id") == api_key_param and k.get("status") == "active":
                    candidates.append((p, k))

        # Choose a working combination: project exists and key active
        for p, k in candidates:
            if not isinstance(p, dict) or not isinstance(k, dict):
                continue
            if p.get("status") in ("deleted",):
                continue
            if k.get("status") != "active":
                continue
            return p, k, None

        # If there is a matching key but it's revoked, that's unauthorized (not not-found)
        for p, k in candidates:
            if isinstance(k, dict) and k.get("status") == "revoked":
                return None, None, _err("UNAUTHORIZED", "API key is revoked.")
        return None, None, _err("UNAUTHORIZED", "Invalid API key.")

    # Validate inputs first
    if not isinstance(diagramRequestId, str) or not diagramRequestId:
        # still try to auth so we can log with context when possible; but validation must be returned
        project, key, auth_err = _authenticate(apiKey)
        _record_usage_event(project.get("id") if project else None,
                            key.get("id") if key else None,
                            "n/a:get_diagram_request",
                            "VALIDATION_ERROR",
                            int((time.time() - t0) * 1000),
                            error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "diagramRequestId must be a non-empty string.")

    project, key, auth_err = _authenticate(apiKey)
    if auth_err:
        _record_usage_event(None, None, "n/a:get_diagram_request", auth_err["error"]["code"], int((time.time() - t0) * 1000),
                            error_code=auth_err["error"]["code"])
        return auth_err

    # Update last_used_at on successful authentication
    api_keys = _load("api_keys.json")
    now_ts = _now_utc_iso()
    updated = False
    for row in api_keys:
        if isinstance(row, dict) and row.get("id") == key.get("id"):
            row["last_used_at"] = now_ts
            row["updated_at"] = now_ts
