def create_api_key(apiKey, name, **_extra):
    import json, os, datetime, time, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0011000" if __import__("os").path.isdir("./environment_mix/0011000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
