    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _next_usage_id(usage, ts_iso):
        base = "mmd_uev_" + ts_iso.replace("-", "").replace(":", "").replace("Z", "")
        return f"{base}_{len(usage) + 1}"

    def _record_call_log(project_id, api_key_id, status_str, error_code=None):
        usage = _load("usage_events.json")
        ts = _now_utc_iso()
        usage.append({
            "id": _next_usage_id(usage, ts),
            "project_id": project_id or "unknown",
            "api_key_id": api_key_id or "unknown",
            "request_id": "n/a:create_api_key",
            "event_type": "request_received",
            "billable_units": 0,
            "mermaid_chars": 1,
            "output_bytes": None,
            "occurred_at": ts,
            "created_at": ts,
            "updated_at": ts
        })
        _save("usage_events.json", usage)

    def _auth_key(api_key_param, api_keys, projects):
        if not isinstance(api_key_param, str) or len(api_key_param) < 8:
            return None, None, _err("VALIDATION_ERROR", "apiKey must be a string with minLength 8.")
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_param:
                return proj_by_id.get(k.get("project_id")), k, None
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            kp = k.get("key_prefix")
            if isinstance(kp, str) and (api_key_param == kp or api_key_param.startswith(kp)):
                return proj_by_id.get(k.get("project_id")), k, None
        if api_key_param in proj_by_id:
            p = proj_by_id.get(api_key_param)
            for k in api_keys:
                if isinstance(k, dict) and k.get("project_id") == api_key_param and k.get("status") == "active":
                    return p, k, None
            return p, None, _err("UNAUTHORIZED", "No active API key exists for the provided project.")
        return None, None, _err("UNAUTHORIZED", "Invalid API key (no matching id or key_prefix in store).")

    try:
        # Validate inputs
        if not isinstance(apiKey, str) or len(apiKey) < 8:
            _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "apiKey must be a string of length >= 8.")
        if not isinstance(name, str) or not (1 <= len(name) <= 80):
            _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a string with length between 1 and 80.")

        projects = _load("projects.json")
        api_keys = _load("api_keys.json")

        project, caller_key, auth_err = _auth_key(apiKey, api_keys, projects)
        if auth_err:
            _record_call_log(None, None, "error", error_code=auth_err["error"]["code"])
            return auth_err
        if not project or not isinstance(project, dict):
            _record_call_log(None, caller_key.get("id") if caller_key else None, "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Authenticated key does not reference a valid project.")
        if not caller_key or caller_key.get("status") != "active":
            _record_call_log(project.get("id"), caller_key.get("id") if caller_key else None, "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key is revoked; cannot manage keys.")
        if project.get("status") != "active":
            _record_call_log(project.get("id"), caller_key.get("id"), "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", f"Project is not active (status='{project.get('status')}'); cannot create keys.")

        # Update last_used_at for caller key
        now_iso = _now_utc_iso()
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == caller_key.get("id"):
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break

        # Generate new secret once; store only hash (plaintext not stored)
        secret = "mmd_sk_" + secrets.token_urlsafe(24)
        key_prefix = secret[:8]

        # Enforce unique(project_id, key_prefix)
        for k in api_keys:
            if isinstance(k, dict) and k.get("project_id") == project.get("id") and k.get("key_prefix") == key_prefix:
                # extremely unlikely; retry a few times
                for _ in range(5):
                    secret = "mmd_sk_" + secrets.token_urlsafe(24)
                    key_prefix = secret[:8]
                    if not any(isinstance(x, dict) and x.get("project_id") == project.get("id") and x.get("key_prefix") == key_prefix for x in api_keys):
                        break
                else:
                    _record_call_log(project.get("id"), caller_key.get("id"), "error", error_code="CONFLICT")
                    _save("api_keys.json", api_keys)
                    return _err("CONFLICT", "Could not allocate a unique key_prefix; please retry.")

        # Create id
        new_id = "mmd_key_" + secrets.token_hex(12).lower()

        # Hash secret for storage (auth never checks against this hash; secret is returned only now)
        key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()

        new_row = {
            "id": new_id,
            "project_id": project.get("id"),
            "key_prefix": key_prefix,
            "key_hash": key_hash,
            "status": "active",
            "name": name,
            "last_used_at": None,
            "revoked_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        api_keys.append(new_row)
        _save("api_keys.json", api_keys)

        _record_call_log(project.get("id"), caller_key.get("id"), "ok")

        return {
            "api_key_secret": secret,
            "api_key": {
                "id": new_row["id"],
                "project_id": new_row["project_id"],
                "key_prefix": new_row["key_prefix"],
                "status": new_row["status"],
                "name": new_row["name"],
                "last_used_at": new_row["last_used_at"],
                "revoked_at": new_row["revoked_at"],
                "created_at": new_row["created_at"],
                "updated_at": new_row["updated_at"]
            },
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }
    except Exception as e:
        _record_call_log(None, None, "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

