    if status is not None:
        cur = target.get("status")
        if cur == "revoked" and status == "active":
            _record_usage_event(project.get("id"), caller_key.get("id"), target.get("id"), "INVALID_TRANSITION", int((time.time() - t0) * 1000))
            return _err("INVALID_TRANSITION", "Cannot reactivate a revoked API key (revoked → active is not allowed).")
        if cur == "active" and status == "revoked":
            target["status"] = "revoked"
            target["revoked_at"] = now_ts
            target["updated_at"] = now_ts
        elif cur == status:
            # idempotent no-op allowed but must still be an effect if other fields change; we'll allow if name updates
            pass
        elif cur == "revoked" and status == "revoked":
            pass
        elif cur == "active" and status == "active":
            pass
        else:
            _record_usage_event(project.get("id"), caller_key.get("id"), target.get("id"), "INVALID_TRANSITION", int((time.time() - t0) * 1000))
            return _err("INVALID_TRANSITION", f"Illegal status transition: {cur} → {status}.")

        # Maintain constraint: revoked_at null when active; not null when revoked
        if target.get("status") == "active":
            target["revoked_at"] = None
        else:
            if target.get("revoked_at") is None:
                target["revoked_at"] = now_ts

    if name is not None:
        target["name"] = name
        target["updated_at"] = now_ts

    # No success without effect: ensure something changed
    original = api_keys[target_idx]
    # Since target is a reference in list, compare against a snapshot is hard; instead detect if updated_at set by us
    # If neither status nor name provided, it's invalid (no mutable fields requested)
    if status is None and name is None:
        _record_usage_event(project.get("id"), caller_key.get("id"), target.get("id"), "VALIDATION_ERROR", int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "At least one of 'status' or 'name' must be provided to update an API key.")

    api_keys[target_idx] = target
    _save("api_keys.json", api_keys)

    _record_usage_event(project.get("id"), caller_key.get("id"), target.get("id"), "OK", int((time.time() - t0) * 1000))
    return {
        "api_key": target
    }
